"use client";

import { useState, useEffect, useRef } from "react";
import Link from "next/link";
import { motion, AnimatePresence } from "framer-motion";
import { Menu, X, ChevronDown, ArrowRight } from "lucide-react";
import { cn, navItems } from "@/lib/utils";

export default function Navbar() {
  const [scrolled, setScrolled] = useState(false);
  const [mobileOpen, setMobileOpen] = useState(false);
  const [activeDropdown, setActiveDropdown] = useState<string | null>(null);
  const dropdownRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 16);
    window.addEventListener("scroll", onScroll, { passive: true });
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  useEffect(() => {
    const handler = (e: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(e.target as Node)) {
        setActiveDropdown(null);
      }
    };
    document.addEventListener("mousedown", handler);
    return () => document.removeEventListener("mousedown", handler);
  }, []);

  return (
    <header
      className={cn(
        "fixed top-0 left-0 right-0 z-50 transition-all duration-300",
        scrolled
          ? "bg-white/95 backdrop-blur-md border-b border-neutral-200/60 shadow-[0_2px_16px_rgba(15,23,42,0.06)]"
          : "bg-transparent"
      )}
    >
      <div className="container-medlink">
        <nav className="flex items-center justify-between h-16 lg:h-18">
          {/* Logo */}
          <Link href="/" className="flex items-center gap-2.5 flex-shrink-0">
            <div className="w-8 h-8 rounded-lg bg-gradient-to-br from-brand-500 to-brand-700 flex items-center justify-center shadow-brand-sm">
              <span className="text-white font-bold text-sm font-display">M</span>
            </div>
            <div className="flex flex-col leading-tight">
              <span
                className={cn(
                  "font-bold text-[17px] tracking-tight transition-colors",
                  scrolled ? "text-neutral-900" : "text-white"
                )}
              >
                MedLink
              </span>
              <span
                className={cn(
                  "text-[10px] font-medium tracking-wider uppercase transition-colors",
                  scrolled ? "text-brand-500" : "text-blue-300"
                )}
              >
                Medical Link Services
              </span>
            </div>
          </Link>

          {/* Desktop nav */}
          <div ref={dropdownRef} className="hidden lg:flex items-center gap-1">
            {navItems.map((item) =>
              item.children ? (
                <div key={item.label} className="relative">
                  <button
                    onMouseEnter={() => setActiveDropdown(item.label)}
                    onClick={() =>
                      setActiveDropdown(activeDropdown === item.label ? null : item.label)
                    }
                    className={cn(
                      "flex items-center gap-1.5 px-3.5 py-2 rounded-lg text-sm font-semibold transition-all",
                      scrolled
                        ? "text-neutral-700 hover:text-brand-600 hover:bg-brand-50"
                        : "text-white/85 hover:text-white hover:bg-white/10"
                    )}
                  >
                    {item.label}
                    <ChevronDown
                      size={14}
                      className={cn(
                        "transition-transform duration-200",
                        activeDropdown === item.label ? "rotate-180" : ""
                      )}
                    />
                  </button>

                  <AnimatePresence>
                    {activeDropdown === item.label && (
                      <motion.div
                        initial={{ opacity: 0, y: 8, scale: 0.97 }}
                        animate={{ opacity: 1, y: 0, scale: 1 }}
                        exit={{ opacity: 0, y: 8, scale: 0.97 }}
                        transition={{ duration: 0.18, ease: [0.4, 0, 0.2, 1] }}
                        onMouseLeave={() => setActiveDropdown(null)}
                        className="absolute top-full left-0 mt-2 w-72 bg-white rounded-2xl border border-neutral-200/70 shadow-[0_16px_48px_rgba(15,23,42,0.12)] overflow-hidden"
                      >
                        <div className="p-2">
                          {item.children.map((child) => (
                            <Link
                              key={child.href}
                              href={child.href}
                              onClick={() => setActiveDropdown(null)}
                              className="flex items-start gap-3 px-3 py-2.5 rounded-xl hover:bg-brand-50 group transition-colors"
                            >
                              <div className="w-1.5 h-1.5 rounded-full bg-brand-400 mt-2 flex-shrink-0 group-hover:bg-brand-600 transition-colors" />
                              <div>
                                <p className="text-sm font-semibold text-neutral-900 group-hover:text-brand-700">
                                  {child.label}
                                </p>
                                <p className="text-xs text-neutral-500 mt-0.5 leading-snug">
                                  {child.desc}
                                </p>
                              </div>
                            </Link>
                          ))}
                        </div>
                        <div className="px-4 py-3 bg-neutral-50 border-t border-neutral-100">
                          <Link
                            href="/contact"
                            onClick={() => setActiveDropdown(null)}
                            className="flex items-center gap-2 text-xs font-semibold text-brand-600 hover:text-brand-700"
                          >
                            Demander une démo <ArrowRight size={12} />
                          </Link>
                        </div>
                      </motion.div>
                    )}
                  </AnimatePresence>
                </div>
              ) : (
                <Link
                  key={item.label}
                  href={item.href!}
                  className={cn(
                    "px-3.5 py-2 rounded-lg text-sm font-semibold transition-all",
                    scrolled
                      ? "text-neutral-700 hover:text-brand-600 hover:bg-brand-50"
                      : "text-white/85 hover:text-white hover:bg-white/10"
                  )}
                >
                  {item.label}
                </Link>
              )
            )}
          </div>

          {/* CTA + mobile toggle */}
          <div className="flex items-center gap-3">
            {/* Language switcher */}
            <div className="hidden lg:flex items-center gap-1">
              {["FR", "DE", "IT"].map((lang, i) => (
                <button
                  key={lang}
                  className={cn(
                    "text-xs font-semibold px-2 py-1 rounded transition-colors",
                    i === 0
                      ? scrolled
                        ? "text-brand-600 bg-brand-50"
                        : "text-white bg-white/15"
                      : scrolled
                      ? "text-neutral-500 hover:text-neutral-700"
                      : "text-white/50 hover:text-white/80"
                  )}
                >
                  {lang}
                </button>
              ))}
            </div>

            <Link href="/contact" className="hidden lg:inline-flex btn-primary text-sm py-2.5 px-5">
              Demander une démo
            </Link>

            {/* Mobile toggle */}
            <button
              onClick={() => setMobileOpen(!mobileOpen)}
              className={cn(
                "lg:hidden p-2 rounded-lg transition-colors",
                scrolled ? "text-neutral-700 hover:bg-neutral-100" : "text-white hover:bg-white/10"
              )}
              aria-label="Menu"
            >
              {mobileOpen ? <X size={20} /> : <Menu size={20} />}
            </button>
          </div>
        </nav>
      </div>

      {/* Mobile menu */}
      <AnimatePresence>
        {mobileOpen && (
          <motion.div
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: "auto" }}
            exit={{ opacity: 0, height: 0 }}
            transition={{ duration: 0.25, ease: [0.4, 0, 0.2, 1] }}
            className="lg:hidden overflow-hidden bg-white border-t border-neutral-200"
          >
            <div className="container-medlink py-4 flex flex-col gap-1">
              {navItems.map((item) =>
                item.children ? (
                  <div key={item.label}>
                    <p className="px-3 py-2 text-xs font-bold text-neutral-400 uppercase tracking-wider">
                      {item.label}
                    </p>
                    {item.children.map((child) => (
                      <Link
                        key={child.href}
                        href={child.href}
                        onClick={() => setMobileOpen(false)}
                        className="flex items-center gap-2 px-3 py-2.5 rounded-lg text-sm font-medium text-neutral-700 hover:bg-brand-50 hover:text-brand-600"
                      >
                        <span className="w-1.5 h-1.5 rounded-full bg-brand-400 flex-shrink-0" />
                        {child.label}
                      </Link>
                    ))}
                  </div>
                ) : (
                  <Link
                    key={item.label}
                    href={item.href!}
                    onClick={() => setMobileOpen(false)}
                    className="px-3 py-2.5 rounded-lg text-sm font-semibold text-neutral-700 hover:bg-brand-50 hover:text-brand-600"
                  >
                    {item.label}
                  </Link>
                )
              )}
              <div className="pt-3 border-t border-neutral-100 mt-2">
                <Link href="/contact" onClick={() => setMobileOpen(false)} className="btn-primary w-full justify-center">
                  Demander une démo
                </Link>
              </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </header>
  );
}
